Ext.define('BNK.view.test.BomKlsViewViewController', {
    extend: 'BaseViewController',
    alias: 'controller.test.bomklsview',

    onSelectNews: function() {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var values = {
            boKlsmNewsId : vm.initialConfig.view.config.boKlsmNewsId,
        };

        Ext.Ajax.request({
            headers : {
                serviceId : 'BomKlsSvc.findOneKlsNews',
                //viewId : me.view.parent.id
            },
            jsonData : values,
            success : function(response) {
                var content = Ext.JSON.decode(response.responseText).content;
                var path = content[0].imgMb;
                var img = "<img src=" + path + " style='width:100%; height:auto;'>";
                //refs.title.setHtml(content[0].newsTitle);
                refs.imgCtn.setHtml(img);
            }
        });

    },

    onSelectRept: function() {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var values = {
            boKlsmMgzId : vm.initialConfig.view.config.boKlsmMgzId,
            catDvcd : '001',
        };

        Ext.Ajax.request({
            headers : {
                serviceId : 'BomKlsSvc.findOneKlsMgz',
                //viewId : me.view.parent.id
            },
            jsonData : values,
            success : function(response) {
                var content = Ext.JSON.decode(response.responseText).content;
                var path='';
                var imgAll='';

                for(var i=0; i<content.length; i++ ){
                    path = content[i].imgRt;
                    imgAll += "<img src='" + path + "' style='width:100%; height:auto;'>";
                }


                refs.imgCtn.setHtml(imgAll);
            }
        });

    },

    onSelectTrnd: function() {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var values = {
            boKlsmNewsId : vm.initialConfig.view.config.boKlsmNewsId,
            catDvcd : '002',
        };

        Ext.Ajax.request({
            headers : {
                serviceId : 'BomKlsSvc.findOneKlsMgz',
                //viewId : me.view.parent.id
            },
            jsonData : values,
            success : function(response) {
                var content = Ext.JSON.decode(response.responseText).content;
                var path = content[0].imgMb;
                var img = "<img src=" + path + " style='width:100%; height:auto;'>";
                refs.imgCtn.setHtml(img);
            }
        });

    },

    onScrollEvent: function() {
                        var me = this;
                        var vm = me.getViewModel();
                        var refs = me.getReferences();
                        var mainCtn = refs.mainCtn.el.dom.firstElementChild;
                        console.log('크롤크롤');
                        if(mainCtn.scrollTop > 0 && refs.topBtn.getHidden()===true) {
                            refs.topBtn.setHidden(false);
                        }
                        else if (mainCtn.scrollTop===0 && refs.topBtn.getHidden()===false){
                            refs.topBtn.setHidden(true);
                        }
                        vm.set('last',mainCtn.scrollTop || 0);

    },

    onContainerInitialize: function(component, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();

        refs.mainCtn.bodyElement.on('scroll',function(){
            me.onScrollEvent();
        });

        var cat = vm.initialConfig.view.config.cat;
        if(cat == 'News'){
            this.onSelectNews();
        }

        else if(cat == 'Rept'){
            this.onSelectRept();
        }

        else if(cat == 'Trnd'){
            this.onSelectTrnd();
        }

    },

    onButtonTap: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();
        var mainCtn = refs.mainCtn.el.dom.firstElementChild;
        mainCtn.scrollTop = 0;
    }

});